using AirCare.Api.DTOs;
using AirCare.Api.Models;
using System.Globalization;
namespace AirCare.Api.Services;
public static class DtoMapper {
 public static string Initials(string name) { var parts=name.Split(' ',StringSplitOptions.RemoveEmptyEntries); return parts.Length==0?"ชง":parts[0][..Math.Min(2,parts[0].Length)]; }
 public static TechnicianDto ToDto(TechnicianProfile p,string? area=null) { var match=!string.IsNullOrWhiteSpace(area)&&p.Area.Contains(area,StringComparison.OrdinalIgnoreCase); return new(p.Id,p.User?.FullName??"ช่างแอร์",Initials(p.User?.FullName??"ช่างแอร์"),p.Title,p.Rating,p.ReviewCount,p.JobsCompleted,p.BasePrice,p.Area,p.IsVerified,p.AvailableText,p.SkillsCsv.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries),p.Accent,match?96:p.Rating>=4.8m?91:84,match?"อยู่ในพื้นที่ที่เลือก · มีโปรไฟล์ตรวจสอบแล้ว":p.BasePrice<=500?"ราคาเริ่มต้นเหมาะสม · มีทักษะตรงกับงาน":"คะแนนรีวิวดี · มีประวัติงานบริการ"); }
 public static string DisplayStatus(string s)=>s switch { BookingStates.Pending=>"รอยืนยัน",BookingStates.Confirmed=>"ยืนยันแล้ว",BookingStates.InProgress=>"กำลังดำเนินการ",BookingStates.Completed=>"เสร็จสิ้น",BookingStates.Cancelled=>"ยกเลิก",_=>s };
 public static string NormalizeStatus(string s)=>s.Trim().ToLowerInvariant() switch { "รอยืนยัน" or "pending"=>BookingStates.Pending,"ยืนยันแล้ว" or "confirmed"=>BookingStates.Confirmed,"กำลังดำเนินการ" or "inprogress" or "in progress"=>BookingStates.InProgress,"เสร็จสิ้น" or "completed"=>BookingStates.Completed,"ยกเลิก" or "cancelled" or "canceled"=>BookingStates.Cancelled,_=>"" };
 public static BookingDto ToDto(Booking b) { var d=b.ScheduledAt; return new(b.Id,b.Code,b.Customer?.FullName??"ลูกค้า",b.TechnicianId,b.Technician?.User?.FullName??"ช่างแอร์",Initials(b.Technician?.User?.FullName??"ช่างแอร์"),b.Service,b.UnitLabel,b.Address,d.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),d.ToString("HH:mm",CultureInfo.InvariantCulture),b.Price,DisplayStatus(b.Status),b.CreatedAt.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)); }
 public static AirConditionerDto ToDto(AirConditioner u)=>new(u.Id,u.Label,u.Room,u.Brand,u.Model,u.Type,u.LastServiceDate?.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)??"",u.NextServiceDate?.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)??"",u.Health,u.SerialNumber,u.Services.OrderByDescending(s=>s.Date).Select(s=>new ServiceRecordDto(s.Id,s.Date.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),s.TechnicianName,s.Service,s.Price,s.Summary,s.Status==BookingStates.Completed?"เสร็จสิ้น":"รอตรวจสอบ")).ToList());
 public static BatchBookingDto ToDto(BatchBooking b)=>new(b.Id,b.Code,b.BuildingName,b.Address,b.UnitCount,b.CompletedUnits,b.ScheduledDate.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),b.Status switch{"Confirmed"=>"ยืนยันแล้ว","InProgress"=>"กำลังดำเนินการ","Completed"=>"เสร็จสิ้น","Cancelled"=>"ยกเลิก",_=>"รอช่างเสนอราคา"},b.Quote);
}